trait LayerObject {                        // abstract + concrete members
  def id: Long                             // required (abstract) member
  def describe: String
  private var version = 0
  def touch(): Unit = version += 1         // provided (concrete) member
}

class User(val id: Long, val email: String) extends LayerObject {
  def describe: String = s"user $id"
}
